  if (last >= 2) {
    var col = sh.getRange(2, 1, last - 1, 1).getValues();
    for (var i = 0; i < col.length; i++) if (str_(col[i][0]).toLowerCase() === key) { cache.put('prow:' + key, String(i + 2), 21600); return i + 2; }
  }
