    var r = data[o.Email.toLowerCase()] || [0, 0, 0, 0];
    students.push({ o: o, r: r, family: H['Family email'] === undefined ? '' : str_(v[H['Family email']]) });
    add('all', r); add('c:' + o.Class, r);
