    var k = str_(x[1]).toLowerCase(), status = str_(x[7]);
    if (!keys[k] || str_(x[4]) === 'gc' || /undone|declined|refunded/i.test(status)) return;
    (bought[k] = bought[k] || []).push([cellDay_(x[0]), str_(x[5]), status === 'Gift' ? 'Gift from teacher' : status === 'Requested' ? 'Waiting for approval' : status === 'Available' ? 'Ready to use' : status]);
