    var top = list.reduce(function (m, x) { return Math.max(m, x[0]); }, 0);
    var lead = top > 0 ? list.filter(function (x) { return x[0] === top; }) : [];
    var o = { top: top, ties: lead.length, lead: lead.slice(0, 3).map(function (x) { return x[1]; }), of: list.length, place: 0, mine: 0 };
    if (mine !== undefined) { o.mine = mine; o.place = 1 + list.filter(function (x) { return x[0] > mine; }).length; }
