    g.files.sort(function (a, b) { return a.n - b.n; });
    if (g.files.length > 1) { var used = {}; g.files.forEach(function (f) { if (f.label) used[f.label] = 1; }); var next = 1; g.files.forEach(function (f) { if (!f.label) { while (used[String(next)]) next++; f.label = String(next); used[f.label] = 1; } }); g.files.sort(function (a, b) { return Number(a.label) - Number(b.label); }); }
