      vals[i][3] = f0.name; vals[i][4] = f0.id; vals[i][5] = h.status; if (g.files.length > 1) vals[i][8] = f0.label;
      colors[i] = [h.status === 'Matched' ? '#d9f2d9' : '#fff2b3']; n[h.status === 'Matched' ? 'm' : 'c']++;
      extraRows(vals[i], g.files.slice(1), h.status);
