    if (g.files.length === 1 && numbered) key = normName_(g.files[0].name).replace(/ \d{1,2}$/, '').replace(/ /g, '');
    if (numbered) vals.forEach(function (v, i) { if (home < 0 && str_(v[1]) && str_(v[4]) && wordVariants_(v[1], v[2]).some(function (w) { return w.replace(/ /g, '') === key; })) home = i; });
    if (home < 0) { g.files.forEach(function (f) { leftovers.push({ id: f.id, name: f.name }); }); return; }
    if (g.files.length === 1 && !g.files[0].label) g.files[0].label = (/ (\d{1,2})$/.exec(normName_(g.files[0].name)) || [])[1] || '';
