  var files = listFolder_(u.folder), have = {}, C = unitCols_(sh);
  unitRows_(sh, C).forEach(function (v) { if (str_(v[4])) have[str_(v[4])] = 1; });
  var add = [], words = 0, extra = 0, asSpace = dashIsSpace_(files);
