    if (str_(t.sheet.getRange(1, 1).getValue()) === SOTD_HEAD[0] && /^Shown on/.test(str_(t.sheet.getRange(1, 8).getValue()))) {      // version 3.43's layout: "Shown on" moves from H to J to make room for Course and Use from
      if (t.sheet.getMaxColumns() < SOTD_HEAD.length) t.sheet.insertColumnsAfter(t.sheet.getMaxColumns(), SOTD_HEAD.length - t.sheet.getMaxColumns());
      var n43 = t.sheet.getLastRow() - 1;
      if (n43 > 0) { var shown43 = t.sheet.getRange(2, 8, n43, 1).getDisplayValues(); t.sheet.getRange(2, 10, n43, 1).setNumberFormat('@').setValues(shown43); t.sheet.getRange(2, 8, n43, 2).clearContent(); }
      t.sheet.getRange(1, 1, 1, SOTD_HEAD.length).setValues([SOTD_HEAD]).setFontWeight('bold').setBackground('#e8eefc');
    }
    if (str_(t.sheet.getRange(1, 1).getValue()) === SOTD_OLD[0]) {        // the old Sign of the Day layout: move any rows over (nothing is lost) and switch the headings
      var oldRows = rows_(t.sheet, 2, SOTD_OLD.length);
      if (t.sheet.getMaxColumns() < SOTD_HEAD.length) t.sheet.insertColumnsAfter(t.sheet.getMaxColumns(), SOTD_HEAD.length - t.sheet.getMaxColumns());
      if (oldRows.length) t.sheet.getRange(2, 1, oldRows.length, SOTD_HEAD.length).setValues(oldRows.map(function (r) { return [str_(r[4]) || str_(r[3]), str_(r[1]), '', '', '', '', str_(r[2]), '']; }));
      t.sheet.getRange(1, 1, 1, SOTD_HEAD.length).setValues([SOTD_HEAD]).setFontWeight('bold').setBackground('#e8eefc');
    }
