/* ───────── 4.21 LIVING SCREENSAVERS + MEET THE RESIDENTS (Colleen, 2026-10-17), the same feature as the Hall Pass Kiosk's
   (checkin/Code.js; ported, names prefixed ls / LS_). Teacher only, through api_ls. Tabs: "Living Screensavers", "Living Residents". ───────── */
function lsTab_(name, head) { var t = ensureTab_(name, head); ensureHead_(t.sheet, head); return t.sheet; }
/** Teacher: one entry for every Living Screensavers action (the page calls api_ls(auth, name, args)). */
function api_ls(auth, fn, args) {
  requireTeacher_();
  var ok = { getLiveCams: getLiveCams, saveLiveCam: saveLiveCam, setLiveCamFavorite: setLiveCamFavorite, deleteLiveCam: deleteLiveCam, moveLiveCam: moveLiveCam, lookupLiveCam: lookupLiveCam,
    getLiveResidents: getLiveResidents, saveLiveResident: saveLiveResident, deleteLiveResident: deleteLiveResident, moveLiveResident: moveLiveResident, uploadLiveResidentPhoto: uploadLiveResidentPhoto };
  if (!ok[fn]) throw new Error('Unknown Living Screensavers action.');
  return wire_(ok[fn].apply(null, Array.isArray(args) ? args : []));
}
