    var o = readStu_(sh, row), fs = ss_().getSheetByName(TABS.fsstats);
    if (doneKey) { var saved = parse_(cache.get(doneKey), null); if (saved) { var again = fsStatsFind_(fs, id.key); return { saved: 1, again: true, me: publicMe_(o, st), res: saved.res, stats: fsStatsObj_(again.row) }; } }
