/* ───────── 3.69 backups ─────────
   A full copy of this spreadsheet goes into the Drive folder "ASL Study backups": every Sunday night (a trigger that Set up or repair
   turns on), before Start a new school year, and whenever the teacher picks ASL Study > Back up this sheet now. The newest 12 weekly
   copies are kept (older weekly ones go to the Drive trash, which keeps them 30 more days); the others are never removed. */
var BACKUP_FOLDER = 'ASL Study backups', BACKUP_KEEP = 12;
function backupFolder_() { var it = DriveApp.getFoldersByName(BACKUP_FOLDER); return it.hasNext() ? it.next() : DriveApp.createFolder(BACKUP_FOLDER); }
function backupNow_(why) {
  var ss = ss_(), folder = backupFolder_(), name = ss.getName() + ' backup ' + dayStr_() + ' (' + why + ')';
  var copy = DriveApp.getFileById(ss.getId()).makeCopy(name, folder);
  if (why === 'weekly') {
    var files = folder.getFiles(), weekly = [];
    while (files.hasNext()) { var f = files.next(); if (/\(weekly\)$/.test(f.getName())) weekly.push(f); }
    weekly.sort(function (a, b) { return b.getDateCreated() - a.getDateCreated(); });
    weekly.slice(BACKUP_KEEP).forEach(function (f) { try { f.setTrashed(true); } catch (e) {} });
  }
  PropertiesService.getDocumentProperties().setProperty('lastBackup', dayStr_() + '|' + why);
  return name;
}
/** The weekly trigger calls this; a backup that fails emails the teacher. */
function weeklyBackup() {
  try { backupNow_('weekly'); }
  catch (e) { try { MailApp.sendEmail(Session.getEffectiveUser().getEmail(), 'ASL Study: the weekly backup did not work', 'The weekly copy of your ASL Study sheet could not be made: ' + String(e && e.message || e) + '\n\nOpen the sheet and choose ASL Study > Back up this sheet now.'); } catch (e2) {} }
}
function backupsOn_() {
  try {
    var have = ScriptApp.getProjectTriggers().some(function (t) { return t.getHandlerFunction() === 'weeklyBackup'; });
    if (!have) ScriptApp.newTrigger('weeklyBackup').timeBased().onWeekDay(ScriptApp.WeekDay.SUNDAY).atHour(22).create();
    return true;
  } catch (e) { return false; }
}
/** Menu: ASL Study > Back up this sheet now. */
function backupNow() {
  requireTeacher_();
  var ui = SpreadsheetApp.getUi(), name = backupNow_('by hand'), on = backupsOn_();
  ui.alert('Backed up', 'A copy named "' + name + '" is in the Google Drive folder "' + BACKUP_FOLDER + '".' + (on ? ' A weekly copy is also made every Sunday night.' : ''), ui.ButtonSet.OK);
}

