  var o = { url: '', key: '' }; rows_(ss_().getSheetByName(TABS.settings), 2, 2).forEach(function (r) { var k = str_(r[0]); if (k === 'Seating charts: kiosk link') o.url = str_(r[1]); if (k === 'Seating charts: kiosk key') o.key = str_(r[1]); });
