  var body = { seatApi: 1, key: k.key, act: act }; for (var x in (extra || {})) body[x] = extra[x];
  var res = UrlFetchApp.fetch(k.url, { method: 'post', contentType: 'application/json', payload: JSON.stringify(body), muteHttpExceptions: true, followRedirects: true }), out = null;
  try { out = JSON.parse(res.getContentText()); } catch (e) { throw new Error('The Hall Pass Kiosk did not answer (check the kiosk link on the Settings tab).'); }
  if (out && out.error) throw new Error('Hall Pass Kiosk: ' + out.error);
