var SEAT_KEY_RE = /(\d{4,})@/;
function seatIdOf_(email) { var m = SEAT_KEY_RE.exec(str_(email)); return m ? 'ID:' + m[1] : ''; }
/** Turns every student in a chart from one naming into the other with map(name) (seats, pins, near / away / zone rules); unknown names stay. */
