  if (c.seats) Object.keys(c.seats).forEach(function (k) { if (c.seats[k]) c.seats[k] = f(c.seats[k]); });
  if (c.pins) { var p = {}; Object.keys(c.pins).forEach(function (e) { p[f(e)] = c.pins[e]; }); c.pins = p; }
  if (c.rules) c.rules = c.rules.map(function (r) { var r2 = JSON.parse(JSON.stringify(r)); if (r2.a) r2.a = f(r2.a); if (r2.b) r2.b = f(r2.b); return r2; });
