  out.seats = out.seats || {}; Object.keys(cur.seats || {}).forEach(function (k) { var who = cur.seats[k]; if (who && !mine(who) && !out.seats[k] && desks.indexOf(k) >= 0) out.seats[k] = who; });
  out.pins = out.pins || {}; Object.keys(cur.pins || {}).forEach(function (e) { if (!mine(e) && out.seats[cur.pins[e]] === e) out.pins[e] = cur.pins[e]; });
  out.rules = (out.rules || []).concat((cur.rules || []).filter(function (r) { return !mine(r.a) || (r.b && !mine(r.b)); }));
