/* ───────── Copy the picture folders into the teacher's own Drive ─────────
   A copy of the sheet starts out pointing at the shared picture folders. This copies them (subfolders too) into a
   "ASL Study pictures" folder in the teacher's Drive, shares the copies so students can see them, points the Settings
   rows at the copies, and moves the Avatars tab and theme backdrops over to the copied files, keeping names and choices.
   It runs in small batches from the dialog, so a big folder never hits Google's time limit. */
var PIC_FOLDER_SETTINGS = ['Avatar folder link', 'Class game character folder link', 'Theme backdrop folder link', 'Game backgrounds folder link'];
var PIC_COPY_BATCH = 12;
function copyPictures() {
  requireTeacher_();
  var html = '<style>body{font:14px Arial,sans-serif;margin:0;padding:16px;color:#202124}p{line-height:1.45;margin:0 0 10px}button{padding:8px 14px;font-size:14px;border:0;border-radius:6px;background:#1a73e8;color:#fff;cursor:pointer;font-weight:bold}button:disabled{background:#9aa0a6}' +
    '.bar{height:10px;background:#e8eaed;border-radius:99px;margin:12px 0;overflow:hidden}.bar i{display:block;height:100%;width:0;background:#188038;transition:width .3s}#msg{min-height:20px}.err{color:#c5221f}.muted{color:#5f6368;font-size:12px}</style>' +
    '<p>This copies the avatar, game character and backdrop folders into a new <b>ASL Study pictures</b> folder in your own Google Drive, subfolders and all. Then your copy of ASL Study uses your folders instead of the shared ones.</p>' +
    '<p>The copies are shared as Anyone with the link can view, so students can see them. Afterwards you can delete, add or rename pictures in your folders any time.</p>' +
    '<p class="muted">Large folders take a few minutes. Keep this box open until it says Done.</p>' +
    '<button id="go">Copy the folders</button><div class="bar"><i id="fill"></i></div><div id="msg"></div>' +
    '<script>' + DIALOG_ERR_JS + ';var $=function(i){return document.getElementById(i)},jobs=[],map={},done=0;' +
    'function fail(e){$("msg").className="err";$("msg").textContent=errMsg(e);$("go").disabled=false;$("go").textContent="Try again"}' +
    'function step(){if(done>=jobs.length){$("msg").textContent="Finishing up…";google.script.run.withSuccessHandler(function(t){$("fill").style.width="100%";$("msg").className="";$("msg").textContent=t;$("go").textContent="Done";$("go").disabled=false;$("go").onclick=function(){google.script.host.close()}}).withFailureHandler(fail).copyPicsFinish(map);return}' +
    'var part=jobs.slice(done,done+' + PIC_COPY_BATCH + ');google.script.run.withSuccessHandler(function(m){for(var k in m)map[k]=m[k];done+=part.length;$("fill").style.width=Math.round(100*done/jobs.length)+"%";$("msg").textContent="Copied "+done+" of "+jobs.length+" pictures…";step()}).withFailureHandler(fail).copyPicsBatch(part)}' +
    '$("go").onclick=function(){$("go").disabled=true;$("msg").className="";$("msg").textContent="Making your folders…";google.script.run.withSuccessHandler(function(p){if(p.none){$("msg").textContent=p.none;$("go").textContent="Close";$("go").disabled=false;$("go").onclick=function(){google.script.host.close()};return}jobs=p.jobs.filter(function(j){return!map[j[0]]});done=0;step()}).withFailureHandler(fail).copyPicsPlan()}' +
    '<\/script>';
  SpreadsheetApp.getUi().showModalDialog(HtmlService.createHtmlOutput(html).setWidth(480).setHeight(380), 'Copy the picture folders to my Drive');
}
/** Shares a copied file or folder so students can see it: anyone with the link, or failing that (some school accounts) anyone at the school with the link. */
function shareForStudents_(item) {
  try { item.setSharing(DriveApp.Access.ANYONE_WITH_LINK, DriveApp.Permission.VIEW); return 'anyone'; } catch (e) {}
  try { item.setSharing(DriveApp.Access.DOMAIN_WITH_LINK, DriveApp.Permission.VIEW); return 'domain'; } catch (e) {}
  return '';
}
/** Whether this folder already belongs to the teacher (then there is nothing to copy). */
function ownFolder_(folder) {
  try { var o = folder.getOwner(); return !!o && str_(o.getEmail()).toLowerCase() === str_(Session.getEffectiveUser().getEmail()).toLowerCase(); } catch (e) { return false; }
}
/** Step 1: makes the folder tree and returns every picture to copy as [file ID, destination folder ID]. */
function copyPicsPlan() {
  requireTeacher_();
  var own = {}, ps = ss_().getSheetByName(TABS.pics);                  // students' own pictures in the avatar folder stay where they are
  if (ps && ps.getLastRow() > 1) ps.getRange(2, 6, ps.getLastRow() - 1, 1).getValues().forEach(function (r) { var id = str_(r[0]); if (id && !/^data:/.test(id)) own[id] = 1; });
  var root = null, jobs = [], sets = [], seen = {}, missing = [];
  function isPic(f) { return /\.(gif|png|jpe?g|webp|svg)$/i.test(f.getName()) || /^image\//.test(String(f.getMimeType())); }
  function walk(src, dest, depth) {
    var it = src.getFiles();
    while (it.hasNext()) { var f = it.next(); if (!seen[f.getId()] && !own[f.getId()] && isPic(f)) { seen[f.getId()] = 1; jobs.push([f.getId(), dest.getId()]); } }
    if (depth >= 3) return;
    var subs = src.getFolders();
    while (subs.hasNext()) { var sub = subs.next(), d = dest.createFolder(sub.getName()); shareForStudents_(d); walk(sub, d, depth + 1); }
  }
  PIC_FOLDER_SETTINGS.forEach(function (key) {
    var ids = folderIds_(settingVal_(key)), dest = [];
    if (!ids.length) return;
    ids.forEach(function (id) {
      var src; try { src = DriveApp.getFolderById(id); src.getName(); } catch (e) { missing.push(key); dest.push(id); return; }
      if (ownFolder_(src)) { dest.push(id); return; }
      if (!root) { root = DriveApp.createFolder('ASL Study pictures'); shareForStudents_(root); }
      var d = root.createFolder(src.getName()); shareForStudents_(d); dest.push(d.getId());
      walk(src, d, 1);
    });
    sets.push([key, dest]);
  });
  if (missing.length && !root) throw new Error('ASL Study could not open the folder in ' + missing.join(' and ') + '. Check that it is shared as Anyone with the link can view, or ask the person who shared it.');
  if (!root) return { none: 'Your picture folders are already in your own Drive. There is nothing to copy.' };
  PropertiesService.getDocumentProperties().setProperty('piccopy', JSON.stringify({ sets: sets, root: root.getId(), missing: missing }));
  return { jobs: jobs, root: root.getUrl() };
}
/** Step 2 (called again and again): copies a few pictures. Returns { old file ID: new file ID }. */
function copyPicsBatch(jobs) {
  requireTeacher_();
  var out = {}, folders = {};
  (jobs instanceof Array ? jobs : []).slice(0, 40).forEach(function (j) {
    var fid = str_(j && j[0]), did = str_(j && j[1]);
    if (!fid || !did) return;
    var dest = folders[did] || (folders[did] = DriveApp.getFolderById(did)), src = DriveApp.getFileById(fid);
    var c = src.makeCopy(src.getName(), dest); shareForStudents_(c);
    out[fid] = c.getId();
  });
  return out;
}
/** Step 3: points the Settings rows at the copies and moves the Avatars tab and theme backdrops to the copied files. */
function copyPicsFinish(map) {
  requireTeacher_();
  map = map && typeof map === 'object' ? map : {};
  var props = PropertiesService.getDocumentProperties(), job = parse_(props.getProperty('piccopy'), null);
  if (!job) throw new Error('Start again with ASL Study > Copy the picture folders to my Drive.');
  var moved = 0;
  lock_(function () {
    job.sets.forEach(function (s) { setSettingRow_(s[0], s[1].map(function (id) { return 'https://drive.google.com/drive/folders/' + id; }).join('\n')); });
    var av = ss_().getSheetByName(TABS.avatars);
    if (av && av.getLastRow() > 1) {
      var rng = av.getRange(2, 2, av.getLastRow() - 1, 1), vals = rng.getValues();
      vals.forEach(function (r) { var id = media_(r[0]); if (id && map[id]) { r[0] = map[id]; moved++; } });
      rng.setValues(vals);
    }
    var shop = ss_().getSheetByName(TABS.shop);
    if (shop && shop.getLastRow() > 1 && shop.getMaxColumns() >= BACKDROP_COL) {
      var br = shop.getRange(2, BACKDROP_COL, shop.getLastRow() - 1, 1), bv = br.getValues();
      bv.forEach(function (r) { var id = media_(r[0]); if (id && map[id]) r[0] = map[id]; });
      br.setValues(bv);
    }
  });
  props.deleteProperty('piccopy');
  props.setProperty('picsdone', String(Date.now()));                     // the menu item hides itself from now on (Prepare as a template clears this)
  try { buildMenu_(); } catch (e) {}
  cacheDrop_('static'); cacheDrop_('boards'); STATIC_ = null;
  var n = Object.keys(map).length;
  return 'Done. ' + n + (n === 1 ? ' picture was' : ' pictures were') + ' copied into ASL Study pictures in your Drive, and your Settings tab now uses your folders' +
    (moved ? ' (' + moved + ' avatars kept their names and choices)' : '') + '.' + (job.missing && job.missing.length ? ' The folder in ' + job.missing.join(' and ') + ' could not be opened, so it was left as it was.' : '');
}

/* ───────── Make cards from a spreadsheet ─────────
   The teacher brings in any spreadsheet (a tab of this sheet, for example an Excel or CSV file added with File > Import,
   or a Google Sheets link), says which column is each side of the card, and the rows become cards on a unit tab.
   Each side can be text or a picture: a picture link, a Drive file link, an =IMAGE("...") formula, or a picture placed in the cell.
   Text and text: the first side is the Term (typed and chosen), the other the Definition. Text and picture: the text is the Term
   and the picture is shown with it. Two pictures cannot be a card yet (nothing to type or read out), so those rows are listed, not added. */
var IMPORT_MAX_ROWS = 2000, IMPORT_MAX_COLS = 15;
/* Dialog script: a plain explanation for Google's own error when the browser is signed into several Google accounts.
   A dialog's requests go out as the browser's first account, so Google refuses them before this script runs. */
var DIALOG_ERR_JS = 'function errMsg(e){var m=String(e&&e.message||e);return /PERMISSION_DENIED|reading from storage/i.test(m)?"Google blocked this because your browser is signed into more than one Google account. Open this sheet in a window signed into only the account that owns it (a private or incognito window works), then try again.":m}';
function appTab_(name) { for (var k in TABS) if (TABS[k] === name) return true; return false; }
/** Menu: the dialog. */
