  rows_(ss.getSheetByName(TABS.classes), 2, 2).forEach(function (r) { var c = str_(r[1]); if (c && courses.indexOf(c) < 0) courses.push(c); });
  ss.getSheets().forEach(function (s) { var n = s.getName(); if (!appTab_(n) && units.indexOf(n) < 0 && !/^(start here|class rewards|student pictures|match report|weak words|student weak words|class stats)$/i.test(n)) tabs.push(n); });      // only tabs that could hold a word list
  function esc(x) { return String(x).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/"/g, '&quot;'); }
  function opts(list, sel) { return list.map(function (x) { return '<option' + (x === sel ? ' selected' : '') + '>' + esc(x) + '</option>'; }).join(''); }
