/**
 * Adds every GIF in a folder to a unit tab as words in one subunit. The word comes from the file name:
 * version numbers are dropped (several GIFs of one word share the word), and dashes separate meanings.
 * GIFs already on the tab are skipped, so it is safe to run again after adding files to the folder.
 */
function importGifs(unitName, sub, link, course, uTitle, sTitle) {
  requireTeacher_();
  var ss = ss_();
  unitName = str_(unitName); sub = str_(sub);
  var titled = function () { try { setUnitTitles_(unitName, sub, uTitle, sTitle); } catch (e) {} };      // 4.69: optional titles (or later, on the Units tab)
  if (!unitName) throw new Error('Choose the unit these GIFs belong to.');
  if (!folderIds_(link).length) throw new Error('Paste the Drive folder link for the GIFs.');
  var files = listFolder_(link);
  if (!files.length) throw new Error('No GIFs were found in that folder. Check the link, and that the files have finished uploading.');
  var sh = ss.getSheetByName(unitName), made = false;
  if (!sh) {
    if (!str_(course)) throw new Error('There is no tab named "' + unitName + '". Choose New unit and pick its course.');
    sh = createUnitTab_(unitName, str_(course), ''); made = true;
  } else if (!unitRow_(unitName)) throw new Error('"' + unitName + '" is not listed on the Units tab, so it is not a unit.');
  var C = unitCols_(sh), have = {}, asSpace = dashIsSpace_(files), add = [], words = {}, skipped = 0;
  unitRows_(sh, C).forEach(function (v) { if (str_(v[4])) have[str_(v[4])] = 1; });
  groupFiles_(files).forEach(function (g) {
    var en = meaningName_(g.raw, asSpace);
    g.files.forEach(function (f) {
      if (have[f.id]) { skipped++; return; }
      words[en.toLowerCase()] = 1;
      add.push(unitRowOut_(C, [sub, en, '', f.name, f.id, 'Matched', '', '', f.label]));
    });
  });
  if (add.length) {
    var start = Math.max(sh.getLastRow(), 1) + 1;
    sh.getRange(start, C[0], add.length, 1).setNumberFormat('@');                 // keeps 5.10 from turning into 5.1
    sh.getRange(start, 1, add.length, add[0].length).setValues(add);
    sh.getRange(start, C[5], add.length, 1).setBackground('#d9f2d9');
  }
  // remember the folder on the Units tab, so Match GIFs can find new files in it later
  var units = ss.getSheetByName(TABS.units);
  rows_(units, 2, 4).forEach(function (r, i) {
    if (str_(r[0]) !== unitName) return;
    var cur = folderIds_(r[3]), id = folderIds_(link)[0];
    if (cur.indexOf(id) < 0) units.getRange(i + 2, 4).setValue((str_(r[3]) ? str_(r[3]) + '\n' : '') + str_(link));
  });
  cacheDrop_('static');
  var nWords = Object.keys(words).length;
  titled();
  return (made ? 'Created the tab "' + unitName + '".\n' : '') +
    (add.length ? 'Added ' + add.length + ' GIFs as ' + nWords + (nWords === 1 ? ' word' : ' words') + ' to ' + unitName + (sub ? ', subunit ' + sub : '') + '.' : 'Nothing new to add.') +
    (skipped ? '\n' + skipped + ' GIFs were already on the tab and were skipped.' : '') +
    (add.length ? '\n\nCheck the English wording on the new rows at the bottom of the tab. Students see them within five minutes, or right away if you choose ASL Study > Push my changes to the student app now.' : '');
}

function addUnit() {
  requireTeacher_();
  var ui = SpreadsheetApp.getUi(), ss = ss_();
  var a = ui.prompt('Add a unit', 'Name for the new tab, for example: Unit 1', ui.ButtonSet.OK_CANCEL);
  if (a.getSelectedButton() !== ui.Button.OK) return;
  var name = str_(a.getResponseText());
  if (!name) return;
  if (ss.getSheetByName(name)) { ui.alert('There is already a tab named "' + name + '".'); return; }
  var b = ui.prompt('Which course studies ' + name + '?', 'Type it exactly as it appears on the Classes tab, for example: ASL 1', ui.ButtonSet.OK_CANCEL);
  if (b.getSelectedButton() !== ui.Button.OK) return;
  var c = ui.prompt('GIF folder (optional)', 'Paste the Google Drive folder link that holds the GIFs for ' + name + '. You can leave this blank and add it later on the Units tab.', ui.ButtonSet.OK_CANCEL);
  if (c.getSelectedButton() !== ui.Button.OK) return;
  var sh = createUnitTab_(name, str_(b.getResponseText()), str_(c.getResponseText()));
  cacheDrop_('static');
  ss.setActiveSheet(sh);
  ui.alert(name + ' is ready.',
    'If you added a GIF folder, choose ASL Study > Build word list from GIF folder to fill this tab from the file names.\n\n' +
    'Or type your words in the English column and then choose ASL Study > Match GIFs to words.', ui.ButtonSet.OK);
}

function makeLoginCodes() {
  requireTeacher_();
  var sh = stuSheet_(), H = stuHead_(sh), last = sh.getLastRow();
  if (last < 2) { ss_().toast('No students yet.', 'ASL Study'); return; }
  var range = sh.getRange(2, H['Login code'] + 1, last - 1, 1), vals = range.getValues(), n = 0;
  var emails = sh.getRange(2, H.Email + 1, last - 1, 1).getValues();
  var abc = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  vals.forEach(function (v, i) {
    if (str_(v[0]) || !str_(emails[i][0])) return;
    var code = '';
    for (var k = 0; k < 6; k++) code += abc.charAt(Math.floor(Math.random() * abc.length));
    v[0] = code; n++;
  });
  range.setValues(vals);
  ss_().toast('Made ' + n + ' login codes. They are only needed if the app cannot see students’ school accounts.', 'ASL Study', 8);
}

